-- ---------------------------------------------------------------- the file proves what the check will read
select case
  when (select count(*) from public.legal_documents d join (values
    ('privacy', '1.5', date '2026-09-23', '4be8b668083eaaba33898996f0300e7a3379b4a7f6a636590466e00872469562'),
    ('cookie-policy', '1.4', date '2026-09-23', '9293421c816ad7a9e37b04c66c604fac4e62b751deb131dfe2eaeee9c3cab6da'),
    ('refund-policy', '1.8', date '2026-09-24', 'cea2a3009a1a22560cd44c16c1709b73e622d529342ff40b7478f23fb8e05c0c'),
    ('acceptable-use', '1.4', date '2026-09-23', '30b2464f624f1685a342aece421507dbaa613bc187fce57e4966d45e02453833'),
    ('disclaimer', '1.3', date '2026-09-23', 'c0041115714b81fb6cdf5f0865497230a8df72594025b4a76c67c927c85082e8'),
    ('complaints-policy', '1.4', date '2026-09-23', '1768f436a3f258d4e55a2a70ce103ad1efdeba604a9e5dd4d99b9caf2e6eb87d')
  ) t(slug, version, eff, sha) on t.slug = d.slug and t.version = d.version and t.eff = d.effective_date
     and d.content_sha256 = t.sha and encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex') = t.sha) <> 6
    then 'PROBE FAILED: a registry row is not the site''s version, date and body'
  else 'PROBE OK' end as verdict;
